  "implementation": "def solve(case):
    import json

    # Validate required fields
    required = ['min_cluster_size', 'clusters', 'parent']
    for key in required:
        if key not in case:
            raise ValueError(f"Missing required field: '{key}'")

    min_size = case['min_cluster_size']
    clusters_input = case['clusters']
    parent_map = case['parent']

    if not isinstance(clusters_input, list):
        raise ValueError("'clusters' must be a list")
    if not isinstance(parent_map, dict):
        raise ValueError("'parent' must be a dict")

    # Build cluster lookup
    cluster_map = {}
    for cl in clusters_input:
        if not isinstance(cl, dict):
            raise ValueError("Each cluster must be a dict")
        cid = cl.get('cluster_id')
        if not cid or not isinstance(cid, str):
            raise ValueError("Each cluster must have a string 'cluster_id'")
        size = cl.get('size')
        if not isinstance(size, int) or size < 0:
            raise ValueError(f"Cluster '{cid}' has invalid 'size'")
        birth = cl.get('birth_lambda')
        if not isinstance(birth, (int, float)):
            raise ValueError(f"Cluster '{cid}' has invalid 'birth_lambda'")
        exits = cl.get('point_exit_lambdas')
        if not isinstance(exits, list):
            raise ValueError(f"Cluster '{cid}' has invalid 'point_exit_lambdas'")
        if len(exits) != size:
            raise ValueError(f"Cluster '{cid}' size mismatch: sizes {size} but {len(exits)} exit lambdas")
        cluster_map[cid] = cl

    # Validate parent_map keys match cluster ids
    for cid in parent_map:
        if cid not in cluster_map:
            raise ValueError(f"Parent map contains unknown cluster id '{cid}'")
        p = parent_map[cid]
        if p is not None and p not in cluster_map:
            raise ValueError(f"Parent '{p}' of cluster '{cid}' is not a known cluster")

    # Retain clusters with size >= min_cluster_size
    retained = [cl for cl in clusters_input if cl['size'] >= min_size]

    # Compute stability for each retained cluster
    cluster_data = []
    for cl in retained:
        cid = cl['cluster_id']
        birth = cl['birth_lambda']
        exits = cl['point_exit_lambdas']
        stability = sum(max(0, ex - birth) for ex in exits)
        cluster_data.append({
            'cluster_id': cid,
            'size': cl['size'],
            'stability': stability
        })

    # Sort for selection: descending stability, then ascending cluster_id
    sorted_clusters = sorted(cluster_data, key=lambda x: (-x['stability'], x['cluster_id']))

    blocked = set()
    selected = []

    # Helper to get ancestor chain (including itself)
    def get_ancestors(cid):
        chain = []
        current = cid
        while current is not None:
            chain.append(current)
            current = parent_map.get(current)
        return chain

    for cl in sorted_clusters:
        cid = cl['cluster_id']
        if cid in blocked:
            continue
        selected.append(cid)
        # Block this cluster and all its ancestors
        ancestors = get_ancestors(cid)
        blocked.update(ancestors)

    # Sort selected ids for output
    selected_sorted = sorted(selected)

    # Sort clusters output by cluster_id for consistency
    clusters_output = sorted(cluster_data, key=lambda x: x['cluster_id'])

    return {
        'clusters': clusters_output,
        'selected_cluster_ids': selected_sorted
    }
